func (v voucher) clone(db *gorm.DB) voucher {
	v.voucherDo.ReplaceConnPool(db.Statement.ConnPool)
	v.UserVouchers.db = db.Session(&gorm.Session{Initialized: true})
	v.UserVouchers.db.Statement.ConnPool = db.Statement.ConnPool
	v.Orders.db = db.Session(&gorm.Session{Initialized: true})
	v.Orders.db.Statement.ConnPool = db.Statement.ConnPool
	v.Products.db = db.Session(&gorm.Session{Initialized: true})
	v.Products.db.Statement.ConnPool = db.Statement.ConnPool
	return v
}

func (v voucher) replaceDB(db *gorm.DB) voucher {
	v.voucherDo.ReplaceDB(db)
	v.UserVouchers.db = db.Session(&gorm.Session{})
	v.Orders.db = db.Session(&gorm.Session{})
	v.Products.db = db.Session(&gorm.Session{})
	return v
}

